import { useEffect, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'

const FEATURE_LABELS = {
  employee_seniority_years:     'Seniority (Years)',
  total_files_burned:           'Total Files Burned',
  burned_from_other:            'Files Burned (Other Source)',
  num_printed_pages_off_hours:  'Off-Hours Print Pages',
  total_printed_pages:          'Total Print Pages',
  num_entries:                  'Building Entries',
  late_exit_flag:               'Late Exit Count',
  entry_during_weekend:         'Weekend Entries',
  trip_day_number:              'Trip Duration (Days)',
  hostility_country_level:      'Travel Country Risk',
  employee_department:          'Department',
  employee_classification:      'Classification',
  is_contractor:                'Contractor',
}

function ExplanationBlock({ text }) {
  if (!text) return null
  // Split on double-newlines to form paragraphs; keep single \n as line breaks
  const parts = text.split('\n\n')
  return (
    <div>
      {parts.map((part, i) => (
        <p
          key={i}
          style={{
            fontSize: '0.875rem',
            color: 'var(--text-muted)',
            lineHeight: 1.75,
            marginBottom: i < parts.length - 1 ? '0.85rem' : 0,
            whiteSpace: 'pre-wrap',
          }}
        >
          {part}
        </p>
      ))}
    </div>
  )
}

export default function ResultPage() {
  const { state } = useLocation()
  const navigate  = useNavigate()
  const [selectedRow, setSelectedRow] = useState(null)
  const [detailCache, setDetailCache] = useState({})   // rank → full result
  const [detailLoading, setDetailLoading] = useState(false)

  useEffect(() => {
    if (!state?.result) navigate('/')
  }, [state, navigate])

  const result = state?.result
  if (!result) return null

  // ── Batch CSV mode ────────────────────────────────────────────────────────
  if (Array.isArray(result.results)) {
    const rows = result.results
    const maliciousCount = rows.filter(r => r.prediction === 1).length

    async function handleRowClick(i) {
      if (selectedRow === i) { setSelectedRow(null); return }
      setSelectedRow(i)
      const r = rows[i]
      if (detailCache[r.rank]) return   // already fetched
      setDetailLoading(true)
      try {
        const res  = await fetch('/api/explain', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(r.record),
        })
        const data = await res.json()
        if (res.ok) setDetailCache(prev => ({ ...prev, [r.rank]: data }))
      } finally {
        setDetailLoading(false)
      }
    }

    const detailResult = selectedRow !== null
      ? { ...rows[selectedRow], ...(detailCache[rows[selectedRow].rank] ?? {}) }
      : null

    return (
      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/')}>
            ← Back to Analysis
          </button>
          <span style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>
            CSV Batch &mdash; <strong style={{ color: 'var(--text-dim)' }}>{result.total_records ?? rows.length}</strong> scanned
            &nbsp;·&nbsp;
            <strong style={{ color: '#e55' }}>{rows.length}</strong> malicious flagged
            {result.saved_at && (
              <span style={{ marginLeft: '0.75rem', opacity: 0.5, fontSize: '0.75rem' }}>
                saved {new Date(result.saved_at).toLocaleString()}
              </span>
            )}
          </span>
        </div>

        <div className="card" style={{ marginBottom: '1.5rem', padding: 0, overflow: 'hidden' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.85rem' }}>
            <thead>
              <tr style={{ background: 'var(--surface)', borderBottom: '1px solid var(--border)' }}>
                {['Rank', 'Verdict', 'Threat Score', 'High', 'Med', 'Low', 'CSV Row', ''].map(h => (
                  <th key={h} style={{ padding: '0.65rem 1rem', textAlign: 'left', color: 'var(--text-dim)', fontWeight: 600 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => {
                const mal = r.prediction === 1
                const threatPct = (r.probability * 100).toFixed(1)
                const isSelected = selectedRow === i
                return (
                  <tr
                    key={i}
                    onClick={() => handleRowClick(i)}
                    style={{
                      borderBottom: '1px solid var(--border)',
                      cursor: 'pointer',
                      background: isSelected ? 'var(--surface)' : 'transparent',
                    }}
                  >
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--gold)', fontWeight: 700 }}>#{r.rank}</td>
                    <td style={{ padding: '0.6rem 1rem' }}>
                      <span style={{
                        display: 'inline-block',
                        padding: '0.2rem 0.6rem',
                        borderRadius: '4px',
                        fontSize: '0.75rem',
                        fontWeight: 700,
                        background: mal ? 'rgba(220,50,50,0.15)' : 'rgba(50,200,100,0.15)',
                        color: mal ? '#e55' : '#5c5',
                      }}>
                        {mal ? 'MALICIOUS' : 'NORMAL'}
                      </span>
                    </td>
                    <td style={{ padding: '0.6rem 1rem' }}>
                      <span style={{ color: mal ? '#e55' : 'var(--text)', fontWeight: mal ? 700 : 400 }}>
                        {threatPct}%
                      </span>
                    </td>
                    <td style={{ padding: '0.6rem 1rem', color: '#e55' }}>{r.high_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: '#fa0' }}>{r.medium_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--text-dim)' }}>{r.low_risk_count ?? 0}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--text-dim)', fontSize: '0.75rem' }}>{r.row_index}</td>
                    <td style={{ padding: '0.6rem 1rem', color: 'var(--gold)', fontSize: '0.75rem' }}>
                      {isSelected ? 'Hide ▲' : 'Details ▼'}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>

        {selectedRow !== null && (
          detailLoading
            ? <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--gold)' }}>Loading details…</div>
            : <SingleResult result={detailResult} onBack={null} />
        )}
      </div>
    )
  }

  // ── Single result mode ────────────────────────────────────────────────────
  return <SingleResult result={result} onBack={() => navigate('/')} />
}

function SingleResult({ result, onBack }) {
  const isMalicious  = result.prediction === 1
  const pct          = result.confidence_pct ?? Math.round(result.probability * 100)
  const indicators   = result.risk_indicators ?? []
  const importances  = result.global_feature_importance ?? []
  const explanation  = result.manager_explanation ?? ''

  return (
    <div>
      {/* Back row */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
        {onBack && (
          <button className="btn btn-secondary" onClick={onBack}>
            ← Back to Analysis
          </button>
        )}
        {result.profile_name && (
          <span style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>
            Profile: <strong style={{ color: 'var(--gold)' }}>{result.profile_name}</strong>
            {' '}—{' '}{result.profile_title}
          </span>
        )}
      </div>

      {result.demo_mode && (
        <div className="alert alert-info" style={{ marginBottom: '1.25rem' }}>
          <span>⚡</span>
          <span>Running in <strong>DEMO MODE</strong> — model not trained. Results use a heuristic estimator.</span>
        </div>
      )}

      <div className="result-layout">

        {/* ── Verdict ── */}
        <div className={`verdict-card ${isMalicious ? 'verdict-malicious' : 'verdict-normal'}`}>
          <div className="verdict-icon">{isMalicious ? '🚨' : '✅'}</div>
          <div className="verdict-body">
            <div className="verdict-label">
              {isMalicious ? 'Threat Detected' : 'No Threat Detected'}
            </div>
            <div className="verdict-title">
              {isMalicious ? 'MALICIOUS INSIDER ACTIVITY DETECTED' : 'NORMAL EMPLOYEE BEHAVIOUR'}
            </div>
            <div className="verdict-subtitle">
              {isMalicious
                ? 'Elevated risk indicators identified. Recommend immediate security review.'
                : 'Activity patterns are consistent with normal, legitimate behaviour.'}
            </div>

            <div className="confidence-section">
              <div className="confidence-row">
                <span className="conf-label">Model Confidence</span>
                <span className="conf-pct">{pct}%</span>
              </div>
              <div className="conf-bar-bg">
                <div className="conf-bar-fill" style={{ width: `${pct}%` }} />
              </div>
            </div>
          </div>
        </div>

        {/* ── Risk Indicators ── */}
        <div className="card">
          <div className="card-title">
            Risk Indicators
            {indicators.length > 0 && (
              <span style={{ marginLeft: '0.5rem', color: 'var(--text-dim)' }}>
                ({result.high_risk_count ?? 0} high · {result.medium_risk_count ?? 0} medium · {result.low_risk_count ?? 0} low)
              </span>
            )}
          </div>

          {indicators.length === 0 ? (
            <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>
              No significant risk indicators detected.
            </p>
          ) : (
            <div className="risk-list">
              {indicators.map((ind, i) => (
                <div key={i} className={`risk-item risk-${ind.risk_level}`}>
                  <span className="risk-chip">{ind.risk_level}</span>
                  <div>
                    <div className="risk-feature-name">
                      {FEATURE_LABELS[ind.feature] ?? ind.label ?? ind.feature}
                    </div>
                    <div className="risk-explanation">{ind.explanation}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* ── Feature Importance ── */}
        {importances.length > 0 && (
          <div className="card">
            <div className="card-title">Feature Importance (Global)</div>
            <div className="importance-list">
              {importances.slice(0, 12).map((f, i) => (
                <div key={i}>
                  <div className="imp-row">
                    <span className="imp-name">{FEATURE_LABELS[f.feature] ?? f.label ?? f.feature}</span>
                    <span className="imp-pct">{f.importance.toFixed(1)}%</span>
                  </div>
                  <div className="imp-bg">
                    <div className="imp-fill" style={{ width: `${f.bar_width ?? f.importance}%` }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── Manager Briefing ── */}
        {explanation && (
          <div className="card" style={{ gridColumn: '1 / -1' }}>
            <div className="card-title">Manager Briefing</div>
            <ExplanationBlock text={explanation} />
          </div>
        )}

        {/* ── Input Data Summary ── */}
        {result.record && (
          <div className="card" style={{ gridColumn: '1 / -1' }}>
            <div className="card-title">Input Data</div>
            <div className="data-summary-grid">
              {Object.entries(result.record)
                .filter(([k]) => FEATURE_LABELS[k])
                .map(([k, v]) => (
                  <div key={k} className="data-row">
                    <span className="data-key">{FEATURE_LABELS[k]}</span>
                    <span className="data-value">
                      {k === 'is_contractor' ? (v ? 'Yes' : 'No') : String(v)}
                    </span>
                  </div>
                ))}
            </div>
          </div>
        )}

      </div>
    </div>
  )
}
